-- R-058/R-093/R-094/R-095/R-097. Append-only native migration; 001-039 stay frozen.
CREATE TABLE _dg_native_live_timeline_inputs(recording_id text PRIMARY KEY REFERENCES live_recordings(id),snapshot text NOT NULL,snapshot_hash text NOT NULL CHECK(snapshot_hash=encode(sha256(convert_to(snapshot,'UTF8')),'hex')),source_guard text NOT NULL,source_guard_hash text NOT NULL CHECK(source_guard_hash=encode(sha256(convert_to(source_guard,'UTF8')),'hex')),created_at text NOT NULL);
CREATE TABLE _dg_native_live_timeline_execution(recording_id text PRIMARY KEY REFERENCES live_recordings(id),execution text NOT NULL,execution_hash text NOT NULL CHECK(execution_hash=encode(sha256(convert_to(execution,'UTF8')),'hex')),created_at text NOT NULL);
CREATE TABLE _dg_native_live_timeline_outputs(recording_id text PRIMARY KEY REFERENCES live_recordings(id),receipt text NOT NULL,receipt_hash text NOT NULL CHECK(receipt_hash=encode(sha256(convert_to(receipt,'UTF8')),'hex')),created_at text NOT NULL);
CREATE TRIGGER native_live_timeline_input_immutable BEFORE UPDATE OR DELETE ON _dg_native_live_timeline_inputs FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE TRIGGER native_live_timeline_execution_immutable BEFORE UPDATE OR DELETE ON _dg_native_live_timeline_execution FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE TRIGGER native_live_timeline_output_immutable BEFORE UPDATE OR DELETE ON _dg_native_live_timeline_outputs FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
ALTER TABLE live_recordings DROP CONSTRAINT native_live_capture_shape;
ALTER TABLE live_recordings ADD CONSTRAINT native_live_recording_shape CHECK(environment='mock' AND app_env IN('development','sandbox') AND version>0 AND snapshot_hash=encode(sha256(convert_to(snapshot,'UTF8')),'hex') AND source_guard_hash=encode(sha256(convert_to(source_guard,'UTF8')),'hex') AND(
 (capture_kind='local_continuous_output' AND status IN('ready','withdrawn') AND attempts=1 AND asset_id IS NOT NULL AND size BETWEEN 1 AND 134217728 AND sha256 ~ '^[a-f0-9]{64}$' AND snapshot::jsonb->>'pipeline'='native-live-output-capture-v1')
 OR(capture_kind='local_timeline_reconstruction' AND snapshot::jsonb->>'pipeline'='native-live-timeline-v1' AND status IN('queued','rendering','ready','failed','cancelled','withdrawn') AND attempts BETWEEN 0 AND 3 AND((lease_token IS NULL)=(lease_until IS NULL)) AND(status<>'rendering' OR(attempts>0 AND lease_token IS NOT NULL)) AND(status='rendering' OR lease_token IS NULL) AND(status<>'ready' OR(attempts>0 AND asset_id IS NOT NULL AND storage_key IS NOT NULL AND size BETWEEN 1 AND 134217728 AND sha256 ~ '^[a-f0-9]{64}$')) AND((asset_id IS NULL AND storage_key IS NULL AND size IS NULL AND sha256 IS NULL) OR(asset_id IS NOT NULL AND storage_key IS NOT NULL AND size IS NOT NULL AND sha256 IS NOT NULL AND status IN('ready','withdrawn'))))));
CREATE OR REPLACE FUNCTION dg_native_live_capture_guard() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $dg$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Recording history cannot be deleted';END IF;
 IF OLD.capture_kind='local_continuous_output' THEN
  IF to_jsonb(NEW)-ARRAY['status','version','withdrawn_at','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['status','version','withdrawn_at','updated_at'] OR NEW.version<>OLD.version+1 OR NEW.status<>'withdrawn' OR NEW.withdrawn_at IS NULL OR OLD.status='withdrawn' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Actual recording receipt and capture cannot be rewritten';END IF;
 ELSE
  IF NEW.lease_token IS NOT NULL AND(NEW.lease_token,NEW.lease_until) IS DISTINCT FROM(OLD.lease_token,OLD.lease_until) AND current_user::text=(SELECT app_role FROM _dg_native_runtime_control WHERE id=1) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='API role cannot claim or renew timeline execution leases';END IF;
  IF to_jsonb(NEW)-ARRAY['status','version','attempts','lease_token','lease_until','asset_id','storage_key','size','sha256','error_message','withdrawn_at','updated_at'] IS DISTINCT FROM to_jsonb(OLD)-ARRAY['status','version','attempts','lease_token','lease_until','asset_id','storage_key','size','sha256','error_message','withdrawn_at','updated_at'] OR NEW.version<OLD.version OR NEW.version>OLD.version+1 OR NEW.attempts<OLD.attempts OR NEW.attempts>OLD.attempts+1 OR(OLD.asset_id IS NOT NULL AND(NEW.asset_id,NEW.storage_key,NEW.size,NEW.sha256) IS DISTINCT FROM(OLD.asset_id,OLD.storage_key,OLD.size,OLD.sha256)) OR(NEW.asset_id IS DISTINCT FROM OLD.asset_id AND NOT(OLD.status='rendering' AND NEW.status='ready')) OR(OLD.withdrawn_at IS NOT NULL AND NEW.withdrawn_at IS DISTINCT FROM OLD.withdrawn_at) OR(NEW.status<>OLD.status AND NOT((OLD.status='queued' AND NEW.status IN('rendering','failed','cancelled','withdrawn')) OR(OLD.status='rendering' AND NEW.status IN('ready','failed','queued','cancelled','withdrawn')) OR(OLD.status='failed' AND NEW.status IN('queued','withdrawn')) OR(OLD.status IN('ready','cancelled') AND NEW.status='withdrawn'))) OR(OLD.status='withdrawn' AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Fixed timeline, monotonic attempts, final file and terminal state are protected';END IF;
 END IF;RETURN NEW;
END $dg$;
CREATE FUNCTION dg_native_queue_live_timeline(target text,rid text,snapshot_text text,snapshot_digest text,guard_text text,guard_digest text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE s live_sessions;v jsonb:=snapshot_text::jsonb;g jsonb:=guard_text::jsonb;segments jsonb;deadline text;at_time text:=dg_utc_now();initial_status text:='queued';reason text;prior text;
BEGIN
 SELECT * INTO STRICT s FROM live_sessions WHERE id=target FOR UPDATE;
 SELECT id INTO prior FROM live_recordings WHERE session_id=target;IF prior IS NOT NULL THEN RETURN prior;END IF;
 SELECT coalesce(jsonb_agg(segment::jsonb ORDER BY seq),'[]'::jsonb) INTO segments FROM live_segments WHERE session_id=target;
 SELECT min(value) INTO deadline FROM(SELECT j->>'expiresAt' AS value FROM jsonb_array_elements(s.snapshot::jsonb->'sources') j UNION ALL SELECT j->>'expiresAt' FROM jsonb_array_elements(s.snapshot::jsonb->'definition'->'products') j UNION ALL SELECT to_char((s.ended_at::timestamptz AT TIME ZONE 'UTC')+interval '30 days','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) d;
 IF NOT COALESCE(s.status='ended' AND s.started_at IS NOT NULL AND s.kind<>'preview' AND s.snapshot::jsonb->'definition'->>'recordingEnabled'='true' AND s.environment='mock' AND s.app_env IN('development','sandbox') AND NOT EXISTS(SELECT 1 FROM live_outputs WHERE session_id=target) AND rid ~ '^[a-f0-9-]{36}$' AND snapshot_digest=encode(sha256(convert_to(snapshot_text,'UTF8')),'hex') AND guard_digest=encode(sha256(convert_to(guard_text,'UTF8')),'hex') AND v->>'schemaVersion'='1' AND v->>'pipeline'='native-live-timeline-v1' AND v->>'sessionId'=s.id AND v->>'sessionHash'=s.snapshot_hash AND v->>'stateHash'=s.state_hash AND(v->>'durationMs')::bigint=(s.state::jsonb->>'elapsedMs')::bigint AND(v->>'durationMs')::bigint BETWEEN 0 AND 1800000 AND v->'segments'=segments AND jsonb_array_length(segments)<=600 AND jsonb_typeof(v->'usedCueIds')='array' AND g->>'schemaVersion'='1' AND g->>'pipeline'='native-live-timeline-v1' AND g->>'sessionId'=s.id AND g->>'sessionHash'=s.snapshot_hash AND g->>'stateHash'=s.state_hash AND g->>'segmentsHash' ~ '^[a-f0-9]{64}$' AND g->>'expiresAt'=deadline,false) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Timeline queue must match the actual stopped session and immutable segments';END IF;
 IF(v->>'durationMs')::bigint<1000 THEN initial_status:='failed';reason:='本场播出时间轴不足一秒，不能制作归档；请新建场次完整播出。';
 ELSIF(SELECT count(*) FROM live_recordings WHERE tenant_id=s.tenant_id AND capture_kind='local_timeline_reconstruction' AND status IN('queued','rendering'))>=3 THEN initial_status:='failed';reason:='组织已有三条等待或执行的时间轴归档，完成或取消后可明确重试。';END IF;
 INSERT INTO live_recordings(id,session_id,tenant_id,workspace_id,actor_id,snapshot,snapshot_hash,source_guard,source_guard_hash,status,error_message,environment,app_env,created_at,updated_at,capture_kind) VALUES(rid,s.id,s.tenant_id,s.workspace_id,s.actor_id,snapshot_text,snapshot_digest,guard_text,guard_digest,initial_status,reason,'mock',s.app_env,at_time,at_time,'local_timeline_reconstruction');
 INSERT INTO _dg_native_live_timeline_inputs VALUES(rid,snapshot_text,snapshot_digest,guard_text,guard_digest,at_time);RETURN rid;
END $dg$;
CREATE FUNCTION dg_native_commit_live_timeline(target text,token text,receipt_text text,receipt_digest text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE r live_recordings;s live_sessions;i _dg_native_live_timeline_inputs;e _dg_native_live_timeline_execution;v jsonb:=receipt_text::jsonb;o jsonb:=v->'object';p jsonb:=v->'poster';spec jsonb:=v->'specs';at_time text:=dg_utc_now();aid text:=v->>'assetId';uid text:=v->>'uploadId';
BEGIN
 SELECT * INTO STRICT r FROM live_recordings WHERE id=target FOR UPDATE;SELECT * INTO STRICT s FROM live_sessions WHERE id=r.session_id;SELECT * INTO STRICT i FROM _dg_native_live_timeline_inputs WHERE recording_id=r.id;SELECT * INTO STRICT e FROM _dg_native_live_timeline_execution WHERE recording_id=r.id;
 IF NOT COALESCE(r.capture_kind='local_timeline_reconstruction' AND r.status='rendering' AND r.lease_token=token AND r.lease_until>at_time AND r.withdrawn_at IS NULL AND s.status='ended' AND s.invalidated_at IS NULL AND s.snapshot_hash=i.snapshot::jsonb->>'sessionHash' AND s.state_hash=i.snapshot::jsonb->>'stateHash' AND r.snapshot=i.snapshot AND r.snapshot_hash=i.snapshot_hash AND r.source_guard=i.source_guard AND r.source_guard_hash=i.source_guard_hash AND i.source_guard::jsonb->>'expiresAt'>at_time AND NOT EXISTS(SELECT 1 FROM live_outputs WHERE session_id=s.id) AND EXISTS(SELECT 1 FROM memberships m WHERE m.user_id=r.actor_id AND m.tenant_id=r.tenant_id AND m.role='admin' AND m.workspace_ids::jsonb ? r.workspace_id) AND v->>'schemaVersion'='1' AND v->>'pipeline'='native-live-timeline-output-v1' AND v->>'inputHash'=r.snapshot_hash AND v->>'expiresAt'=i.source_guard::jsonb->>'expiresAt' AND v->'execution'=e.execution::jsonb AND receipt_digest=encode(sha256(convert_to(receipt_text,'UTF8')),'hex') AND aid ~ '^[a-f0-9-]{36}$' AND uid ~ '^[a-f0-9-]{36}$' AND o->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$' AND o->>'sha256' ~ '^[a-f0-9]{64}$' AND(o->>'size')::bigint BETWEEN 1 AND 134217728 AND p->>'storage_key' ~ '^[a-f0-9-]{36}\.bin$' AND p->>'sha256' ~ '^[a-f0-9]{64}$' AND(p->>'size')::bigint BETWEEN 1 AND 8388608 AND(spec->>'width')::bigint=1280 AND(spec->>'height')::bigint=720 AND(spec->>'fps')::bigint=24 AND(spec->>'hasAudio')::bigint=1 AND(spec->>'sampleRate')::bigint=48000 AND(spec->>'channels')::bigint=2 AND abs((spec->>'durationMs')::numeric-(i.snapshot::jsonb->>'durationMs')::numeric)<=120 AND(spec->>'durationMs')::bigint BETWEEN 1 AND 1803000,false) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Timeline output needs the current source, original execution and an actual bounded receipt';END IF;
 INSERT INTO uploads VALUES(uid,r.tenant_id,r.workspace_id,r.actor_id,o->>'storage_key',o->>'sha256',(o->>'size')::bigint,'video/mp4',spec::text,at_time);
 INSERT INTO assets(id,tenant_id,workspace_id,upload_id,name,category,synthetic,expires_at,created_at) VALUES(aid,r.tenant_id,r.workspace_id,uid,'按本地节目时间轴重建的归档','reference',1,v->>'expiresAt',at_time);
 INSERT INTO _dg_native_asset_origins VALUES(aid,uid,r.tenant_id,r.workspace_id,o->>'sha256',(o->>'size')::bigint,'live_recording','mock',r.app_env,at_time);
 INSERT INTO video_sources VALUES(aid,p->>'storage_key',p->>'sha256',(p->>'size')::bigint,at_time);
 UPDATE live_recordings SET status='ready',asset_id=aid,storage_key=o->>'storage_key',size=(o->>'size')::bigint,sha256=o->>'sha256',lease_token=NULL,lease_until=NULL,error_message=NULL,version=version+1,updated_at=at_time WHERE id=target;
 INSERT INTO live_recording_origins VALUES(aid,r.id);INSERT INTO _dg_native_live_timeline_outputs VALUES(r.id,receipt_text,receipt_digest,at_time);
 INSERT INTO asset_versions VALUES(aid,1,jsonb_build_object('id',aid,'workspaceId',r.workspace_id,'name','按本地节目时间轴重建的归档','category','reference','version',1,'archived',false,'synthetic',true,'expiresAt',v->>'expiresAt','createdAt',at_time,'mediaType','video/mp4','size',(o->>'size')::bigint,'sha256',o->>'sha256','specs',spec)::text,at_time);RETURN r.id;
END $dg$;
REVOKE ALL ON FUNCTION dg_native_live_capture_guard(),dg_native_queue_live_timeline(text,text,text,text,text,text),dg_native_commit_live_timeline(text,text,text,text) FROM PUBLIC;
